 * Race firstWindow with process exit so failures are actionable and we do not sit until timeout
 * when the main process has already crashed.
 * @param {import('playwright').ElectronApplication} app
 * @param {number} timeoutMs
 */
async function waitForElectronMainWindow(app, timeoutMs) {
    if (!app || typeof app.firstWindow !== 'function') {
        throw new Error('waitForElectronMainWindow: invalid Electron application');
    }
    const proc = typeof app.process === 'function' ? app.process() : null;
    if (!proc) {
        return app.firstWindow({ timeout: timeoutMs });
    }
    let cleaned = false;
    const onExit = (code, signal) => {
        if (cleaned) return;
        cleaned = true;
        proc.removeListener('exit', onExit);
        proc.removeListener('error', onError);
        exitReject(
            new Error(`Electron exited before first window (code=${code}, signal=${signal || 'none'})`),
        );
    };
    const onError = (err) => {
        if (cleaned) return;
        cleaned = true;
        proc.removeListener('exit', onExit);
        proc.removeListener('error', onError);
        exitReject(new Error(`Electron process error before first window: ${err && err.message ? err.message : String(err)}`));
    };
    let exitReject;
    const exitPromise = new Promise((_, reject) => {
        exitReject = reject;
        proc.once('exit', onExit);
        proc.once('error', onError);
    });
    try {
        return await Promise.race([app.firstWindow({ timeout: timeoutMs }), exitPromise]);
    } finally {
        if (!cleaned) {
            cleaned = true;
            proc.removeListener('exit', onExit);
            proc.removeListener('error', onError);
        }
    }
}

