 * Finalize UI: remove JSX `placeholder` attributes and Tailwind `placeholder-*` utilities
 * from src/renderer (JSX/TSX). Uses @babel/parser + @babel/traverse for correct JSX handling.
 */
import fs from 'node:fs';
import path from 'node:path';
import { parse } from '@babel/parser';
import traverse from '@babel/traverse';

const roots = [
    path.join(process.cwd(), 'src', 'renderer', 'src', 'components'),
    path.join(process.cwd(), 'src', 'renderer', 'src', 'pages'),
];

function walk(dir, acc = []) {
    if (!fs.existsSync(dir)) return acc;
    for (const ent of fs.readdirSync(dir, { withFileTypes: true })) {
        if (ent.name.startsWith('.')) continue;
        const p = path.join(dir, ent.name);
        if (ent.isDirectory()) walk(p, acc);
        else if (/\.(jsx|tsx)$/.test(ent.name)) acc.push(p);
    }
    return acc;
}

function stripTailwindPlaceholderClasses(source) {
    let s = source;
    let prev;
    do {
        prev = s;
        s = s.replace(/\splaceholder-[a-z0-9/-]+/gi, '');
        s = s.replace(/placeholder-[a-z0-9/-]+\s+/gi, '');
    } while (s !== prev);
    return s;
}

function stripJsxPlaceholderAttributes(code) {
    let ast;
    try {
        ast = parse(code, {
            sourceType: 'module',
            errorRecovery: true,
            ranges: true,
            plugins: ['jsx', 'typescript', 'optionalChaining', 'nullishCoalescing'],
        });
    } catch {
        return code;
    }

    const removals = [];
    traverse.default(ast, {
        JSXAttribute(path) {
            const n = path.node;
            const name = n.name;
            if (!name || name.type !== 'JSXIdentifier' || name.name !== 'placeholder') return;
            if (!n.range) return;
            let [start, end] = n.range;
            if (start > 0 && code[start - 1] === ' ') start -= 1;
            removals.push([start, end]);
        },
    });

    removals.sort((a, b) => b[0] - a[0]);
    let out = code;
    for (const [s, e] of removals) {
        out = out.slice(0, s) + out.slice(e);
    }
    return out;
}

const files = roots.flatMap((r) => walk(r));
let changed = 0;
for (const f of files) {
    const orig = fs.readFileSync(f, 'utf8');
    let next = stripJsxPlaceholderAttributes(orig);
    next = stripTailwindPlaceholderClasses(next);
    if (next !== orig) {
        fs.writeFileSync(f, next);
        changed++;
    }
}
console.log(`Scanned ${files.length} files, updated ${changed}`);

