/**
 * Mirror an empty directory onto `dir` (/MIR). Often deletes locked trees on Windows
 * where Node unlink still hits EBUSY, then a second rmSync can remove the rest.
 */
function tryRobocopyMirrorEmpty(dir) {
  if (process.platform !== 'win32' || !fs.existsSync(dir)) {
    return false;
  }
  const empty = path.join(os.tmpdir(), `neuralshell-eb-${process.pid}-${Date.now()}`);
  try {
    fs.mkdirSync(empty, { recursive: true });
  } catch {
    return false;
  }
  const dst = path.resolve(dir);
  const r = spawnSync(
    'robocopy',
    [empty, dst, '/MIR', '/R:3', '/W:300', '/NJH', '/NJS', '/NDL', '/NC', '/NS', '/NP', '/NFL'],
    { stdio: 'ignore', cwd: root },
  );
  try {
    fs.rmSync(empty, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
  } catch {
    /* ignore */
  }
  if (r.error || r.status === undefined) {
    return false;
  }
  const code = r.status;
  return code >= 0 && code < 8;
}

