"use strict";

const fs = require("fs");
const path = require("path");

function hasNeuralShellExe(dir) {
  try {
    return fs.existsSync(path.join(dir, "NeuralShell.exe"));
  } catch {
    return false;
  }
}

/**
 * Resolves packaged Windows app root: dist/win-unpacked, or newest dist/__eb_out_*/win-unpacked.
 * @param {string} repoRoot
 * @returns {string}
 */
function resolveWinUnpackedRoot(repoRoot) {
  const primary = path.join(repoRoot, "dist", "win-unpacked");
  if (hasNeuralShellExe(primary)) {
    return primary;
  }
  const dist = path.join(repoRoot, "dist");
  if (!fs.existsSync(dist)) {
    return primary;
  }
  const ebDirs = [];
  for (const name of fs.readdirSync(dist)) {
    if (!name.startsWith("__eb_out_")) {
      continue;
    }
    const full = path.join(dist, name);
    let st;
    try {
      st = fs.statSync(full);
    } catch {
      continue;
    }
    if (!st.isDirectory()) {
      continue;
    }
    ebDirs.push({ full, mtimeMs: st.mtimeMs });
  }
  ebDirs.sort((a, b) => b.mtimeMs - a.mtimeMs);
  for (const { full } of ebDirs) {
    const candidate = path.join(full, "win-unpacked");
    if (hasNeuralShellExe(candidate)) {
      return candidate;
    }
  }
  return primary;
}

/**
 * Copy NSIS installer + blockmap from a fallback directories.output into dist/ (flat).
 * @param {string} repoRoot
 * @param {string | null} relOut relative path like dist/__eb_out_123
 */
function promoteEbOutInstallerArtifacts(repoRoot, relOut) {
  if (!relOut || !String(relOut).replace(/\\/g, "/").includes("__eb_out_")) {
    return;
  }
  const outAbs = path.resolve(repoRoot, ...String(relOut).split(/[/\\]+/));
  if (!fs.existsSync(outAbs)) {
    return;
  }
  const distRoot = path.join(repoRoot, "dist");
  fs.mkdirSync(distRoot, { recursive: true });
  let n = 0;
  for (const name of fs.readdirSync(outAbs)) {
    const src = path.join(outAbs, name);
    let st;
    try {
      st = fs.statSync(src);
    } catch {
      continue;
    }
    if (!st.isFile()) {
      continue;
    }
    const isMainInstaller = /^NeuralShell Setup .+\.exe$/i.test(name) && !/__uninstaller/i.test(name);
    const isBlockmap = /\.exe\.blockmap$/i.test(name) && /setup/i.test(name);
    if (isMainInstaller || isBlockmap) {
      fs.copyFileSync(src, path.join(distRoot, name));
      n += 1;
    }
    if (name === "latest.yml") {
      fs.copyFileSync(src, path.join(distRoot, name));
      n += 1;
    }
  }
  if (n > 0) {
    process.stderr.write(`[run-electron-builder] Copied ${n} artifact(s) from ${relOut} into dist\\.\n`);
  }
}

module.exports = { resolveWinUnpackedRoot, promoteEbOutInstallerArtifacts, hasNeuralShellExe };

