#!/usr/bin/env node
/**
 * Remove Windows electron-builder leftovers: dist/win-unpacked.__stale_* and dist/__eb_out_*.
 * Without --apply, only prints what would be removed.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const dist = path.join(root, "dist");
const apply = process.argv.includes("--apply");
const keepLatestEb = process.argv.includes("--keep-latest-eb-out");

function formatBytes(n) {
  if (!Number.isFinite(n) || n <= 0) return "0 B";
  const u = ["B", "KB", "MB", "GB"];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < u.length - 1) {
    v /= 1024;
    i += 1;
  }
  return `${i === 0 ? v : v.toFixed(2)} ${u[i]}`;
}

function dirSize(dir) {
  let total = 0;
  function walk(d) {
    let entries;
    try {
      entries = fs.readdirSync(d, { withFileTypes: true });
    } catch {
      return;
    }
    for (const e of entries) {
      const p = path.join(d, e.name);
      try {
        if (e.isDirectory()) walk(p);
        else total += fs.statSync(p).size;
      } catch {
        /* skip */
      }
    }
  }
  walk(dir);
  return total;
}

function main() {
  if (!fs.existsSync(dist)) {
    console.log("[clean-win-packaging-stale] no dist/ folder.");
    return;
  }
  const names = fs.readdirSync(dist);
  const stale = names.filter((n) => n.startsWith("win-unpacked.__stale_"));
  let eb = names.filter((n) => n.startsWith("__eb_out_"));
  if (keepLatestEb && eb.length > 1) {
    const scored = eb
      .map((n) => {
        const full = path.join(dist, n);
        try {
          return { n, m: fs.statSync(full).mtimeMs };
        } catch {
          return { n, m: 0 };
        }
      })
      .sort((a, b) => b.m - a.m);
    eb = scored.slice(1).map((x) => x.n);
  }
  const targets = [...stale, ...eb].map((n) => path.join(dist, n));
  const rows = [];
  for (const t of targets) {
    let st;
    try {
      st = fs.statSync(t);
    } catch {
      continue;
    }
    if (!st.isDirectory()) {
      continue;
    }
    rows.push({ path: t, name: path.basename(t), bytes: dirSize(t) });
  }
  if (rows.length === 0) {
    console.log("[clean-win-packaging-stale] nothing to remove.");
    return;
  }
  let sum = 0;
  for (const r of rows) {
    sum += r.bytes;
    console.log(`[clean-win-packaging-stale] ${apply ? "DELETE" : "would remove"} ${r.name} (${formatBytes(r.bytes)})`);
  }
  console.log(`[clean-win-packaging-stale] total ${formatBytes(sum)}`);
  if (!apply) {
    console.log("[clean-win-packaging-stale] dry run. Re-run with --apply to delete (use --keep-latest-eb-out to retain newest __eb_out_*).");
    process.exit(0);
  }
  for (const r of rows) {
    try {
      fs.rmSync(r.path, { recursive: true, force: true, maxRetries: 8, retryDelay: 100 });
    } catch (e) {
      console.error(`[clean-win-packaging-stale] failed: ${r.name}: ${e.message}`);
      process.exit(1);
    }
  }
  console.log("[clean-win-packaging-stale] done.");
}

main();

