  resolveWinUnpackedRoot,
  findNeuralShellInstallerExe,
  resolveVersionedInstallerPath,
  findUpdateMetadataRelPath,
  listWinPackagingStaleDirPaths,
  promoteEbOutInstallerArtifacts,
} = require("../scripts/lib/win-packaged.cjs");

function mkFixture() {
  return fs.mkdtempSync(path.join(os.tmpdir(), "neuralshell-win-packaged-"));
}

function write(base, rel, content = "x") {
  const p = path.join(base, ...rel.split("/"));
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, content, "utf8");
  return p;
}

function rm(base) {
  try {
    fs.rmSync(base, { recursive: true, force: true });
  } catch {
    /* ignore */
  }
}

function testResolveWinUnpackedPrimary() {
  const root = mkFixture();
  try {
    write(root, "dist/win-unpacked/NeuralShell.exe", "exe");
    const got = resolveWinUnpackedRoot(root);
    assert.equal(path.normalize(got), path.join(root, "dist", "win-unpacked"));
  } finally {
    rm(root);
  }
}

function testResolveWinUnpackedEbFallback() {
  const root = mkFixture();
  try {
    write(root, "dist/__eb_out_old/win-unpacked/NeuralShell.exe", "a");
    // Slightly newer mtime on "new"
    write(root, "dist/__eb_out_new/win-unpacked/NeuralShell.exe", "b");
    const oldDir = path.join(root, "dist", "__eb_out_old");
    const newDir = path.join(root, "dist", "__eb_out_new");
    const tOld = Date.now() - 60_000;
    fs.utimesSync(oldDir, tOld, tOld);
    const got = resolveWinUnpackedRoot(root);
    assert.equal(path.normalize(got), path.join(root, "dist", "__eb_out_new", "win-unpacked"));
  } finally {
    rm(root);
  }
}

function testFindInstallerPrefersDistRootOverEbWithSameBasename() {
  const root = mkFixture();
  try {
    const name = "NeuralShell Setup 9.9.9.exe";
    write(root, `dist/${name}`, "root");
    write(root, `dist/__eb_out_1/${name}`, "eb");
    const got = findNeuralShellInstallerExe(root);
    assert.equal(path.basename(got), name);
    assert.ok(!String(got).includes("__eb_out_"), "expected dist-root installer when basename matches");
  } finally {
    rm(root);
  }
}

function testFindInstallerFromEbOnly() {
  const root = mkFixture();
  try {
    write(root, "dist/__eb_out_x/NeuralShell Setup 1.0.0.exe", "e");
    const got = findNeuralShellInstallerExe(root);
    assert.ok(String(got).includes("__eb_out_"));
  } finally {
    rm(root);
  }
}

function testResolveVersionedInstaller() {
  const root = mkFixture();
  try {
    const v = "3.3.3";
    write(root, `dist/__eb_out_z/NeuralShell Setup ${v}.exe`, "ok");
    const got = resolveVersionedInstallerPath(root, v);
    assert.ok(fs.existsSync(got));
    assert.equal(path.basename(got), `NeuralShell Setup ${v}.exe`);
  } finally {
    rm(root);
  }
}

function testFindUpdateMetadataEb() {
  const root = mkFixture();
  try {
    write(root, "dist/__eb_out_a/latest.yml", "version: 1\n");
    fs.utimesSync(path.join(root, "dist", "__eb_out_a"), Date.now() / 1000 - 10, Date.now() / 1000 - 10);
    write(root, "dist/__eb_out_b/latest.yml", "version: 2\n");
    const rel = findUpdateMetadataRelPath(root, { requireNonEmpty: true });
    assert.ok(rel.replace(/\\/g, "/").includes("__eb_out_b"), "expected newest __eb_out dir");
    assert.ok(rel.endsWith("latest.yml"));
  } finally {
    rm(root);
  }
}

function testListStaleDirs() {
  const root = mkFixture();
  try {
    fs.mkdirSync(path.join(root, "dist", "win-unpacked.__stale_1"), { recursive: true });
    fs.mkdirSync(path.join(root, "dist", "__eb_out_9"), { recursive: true });
    const rows = listWinPackagingStaleDirPaths(root);
    assert.equal(rows.length, 2);
    assert.ok(rows.some((r) => r.name.startsWith("win-unpacked.__stale_")));
    assert.ok(rows.some((r) => r.isEbOut));
  } finally {
    rm(root);
  }
}

function testPromoteCopiesFlat() {
  const root = mkFixture();
  try {
    const out = path.join(root, "dist", "__eb_out_promo");
    fs.mkdirSync(out, { recursive: true });
    write(root, "dist/__eb_out_promo/NeuralShell Setup 2.0.0.exe", "exe");
    write(root, "dist/__eb_out_promo/NeuralShell Setup 2.0.0.exe.blockmap", "bm");
    write(root, "dist/__eb_out_promo/latest.yml", "v: 1\n");
    write(root, "dist/__eb_out_promo/SHA256SUMS.txt", "sum\n");
    promoteEbOutInstallerArtifacts(root, "dist/__eb_out_promo");
    assert.ok(fs.existsSync(path.join(root, "dist", "NeuralShell Setup 2.0.0.exe")));
    assert.ok(fs.existsSync(path.join(root, "dist", "latest.yml")));
    assert.ok(fs.existsSync(path.join(root, "dist", "SHA256SUMS.txt")));
  } finally {
    rm(root);
  }
}

function main() {
  testResolveWinUnpackedPrimary();
  testResolveWinUnpackedEbFallback();
  testFindInstallerPrefersDistRootOverEbWithSameBasename();
  testFindInstallerFromEbOnly();
  testResolveVersionedInstaller();
  testFindUpdateMetadataEb();
  testListStaleDirs();
  testPromoteCopiesFlat();
  console.log("win-packaged-paths test passed.");
}

main();

#!/usr/bin/env node
/**
 * Preflight for Windows desktop packaging (run from repo root).
 * Non-Windows: exits 0 with a skip message.
 */
"use strict";

const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");

function main() {
  if (process.platform !== "win32") {
    console.log("[doctor-win-build] Skipped (not win32).");
    return;
  }

  const issues = [];
  const ok = [];

  function need(rel, hint) {
    const abs = path.join(root, ...rel.split("/"));
    if (fs.existsSync(abs)) {
      ok.push(rel);
    } else {
      issues.push({ rel, hint });
    }
  }

  need("node_modules/electron/package.json", "npm ci");
  need("node_modules/electron-builder/package.json", "npm ci");
  need("node_modules/.bin/electron-builder.cmd", "npm ci");
  need("node_modules/undici/package.json", "npm ci (undici is required for Electron zip download)");

  const asar = path.join(root, "dist", "win-unpacked", "resources", "app.asar");
  if (fs.existsSync(asar)) {
    try {
      const fd = fs.openSync(asar, "r");
      fs.closeSync(fd);
      ok.push("dist/win-unpacked/resources/app.asar is readable");
    } catch (e) {
      issues.push({
        rel: "dist/win-unpacked/resources/app.asar",
        hint: `locked or unreadable (${e.code || e.message}) — close NeuralShell, Electron dev runs, Explorer under dist\\, IDE previews`,
      });
    }
  } else {
    ok.push("no dist/win-unpacked yet (normal before first successful build)");
  }

  console.log("[doctor-win-build] checks:");
  for (const x of ok) {
    console.log(`  OK  ${x}`);
  }
  for (const x of issues) {
    console.log(`  FIX ${x.rel} — ${x.hint}`);
  }

  if (issues.length) {
    console.error(`\n[doctor-win-build] FAILED (${issues.length} issue(s)).`);
    process.exit(1);
  }
  console.log("\n[doctor-win-build] all checks passed.");
}

main();

