/**
 * One-off / agent metrics: line counts from `git ls-files` (tracked only).
 * Run: node scripts/scan-repo-lines.cjs
 */
"use strict";

const { execSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const files = execSync("git ls-files", { encoding: "utf8", cwd: root })
  .trim()
  .split(/\r?\n/)
  .filter(Boolean);

function lineCount(abs) {
  return fs.readFileSync(abs, "utf8").split("\n").length;
}

function skip(rel) {
  if (rel.startsWith("dist-renderer/")) return true;
  if (rel.startsWith("coverage/")) return true;
  if (rel.startsWith(".snapshots/")) return true;
  if (rel === "package-lock.json" || rel.endsWith("/package-lock.json")) return true;
  return false;
}

const B = {
  src_renderer: 0,
  src_main: 0,
  tear: 0,
  scripts: 0,
  e2e: 0,
  tests: 0,
  docs: 0,
  workflows: 0,
  governance: 0,
  other: 0,
};

let skippedLines = 0;
let countedLines = 0;

for (const rel of files) {
  const abs = path.join(root, rel);
  let n;
  try {
    n = lineCount(abs);
  } catch {
    continue;
  }
  if (skip(rel)) {
    skippedLines += n;
    continue;
  }
  countedLines += n;
  if (rel.startsWith("src/renderer/")) {
    B.src_renderer += n;
  } else if (rel.startsWith("src/")) {
    B.src_main += n;
  } else if (rel.startsWith("tear/")) {
    B.tear += n;
  } else if (rel.startsWith("scripts/")) {
    B.scripts += n;
  } else if (rel.startsWith("e2e/")) {
    B.e2e += n;
  } else if (rel.startsWith("tests/")) {
    B.tests += n;
  } else if (rel.startsWith("docs/") || rel.endsWith(".md")) {
    B.docs += n;
  } else if (rel.startsWith(".github/")) {
    B.workflows += n;
  } else if (rel.startsWith("governance/")) {
    B.governance += n;
  } else {
    B.other += n;
  }
}

const handwritten = B.src_main + B.src_renderer + B.tear + B.scripts + B.e2e + B.tests;

console.log(
  JSON.stringify(
    {
      tracked_files: files.length,
      counted_lines_excluding_dist_renderer_lockfiles: countedLines,
      skipped_lines_dist_renderer_etc: skippedLines,
      buckets: B,
      handwritten_code_and_tests_lines_approx: handwritten,
    },
    null,
    2,
  ),
);

