    const settingsDrawer = page.locator('[data-testid="settings-drawer"]');
    // Scope to drawer so tab switches / React remounts do not leave a stale page-level <select> locator.
    const providerSelect = settingsDrawer.locator('[data-testid="settings-provider-select"]');
    const closeBtn = page.locator('[data-testid="settings-close-btn"]');

    if (await settingsDrawer.isVisible().catch(() => false)) {
        await closeBtn.click({ timeout: 5000, force: true }).catch(() => {});
        await page.waitForTimeout(200);
    }

    const opened = await ensureSettingsDrawerOpen();
    if (!opened) {
        test.skip(true, 'Settings drawer is unavailable in this build profile');
    }
    await expect(providerSelect).toBeVisible({ timeout: 20000 });
    // Kill switch row is below the provider block; avoid asserting it before we scroll the drawer.
    const drawerScroll = settingsDrawer.locator('.overflow-y-auto').first();
    await drawerScroll.evaluate((el) => {
        try {
            el.scrollTop = 0;
        } catch {
            /* ignore */
        }
    }).catch(() => {});
    await providerSelect.scrollIntoViewIfNeeded().catch(() => {});
    // Avoid locator.evaluate stability waits on <select> while SettingsDrawer hydrates (Windows CI).
    await providerSelect.waitFor({ state: 'visible', timeout: 60000 });
    await page.waitForTimeout(200);
    const hasOpenRouter = await page.evaluate(() => {
        const el = document.querySelector('[data-testid="settings-provider-select"]');
        if (!el) return false;
        return [...el.options].some((o) => String(o.value) === 'openrouter');
    });
    if (!hasOpenRouter) {
        await page.getByTestId('settings-preset-openrouter-btn').click({ timeout: 10000 }).catch(() => {});
        await page.waitForTimeout(400);
    }
    const hasOpenRouterNow = await page.evaluate(() => {
        const el = document.querySelector('[data-testid="settings-provider-select"]');
        if (!el) return false;
        return [...el.options].some((o) => String(o.value) === 'openrouter');
    });
    if (!hasOpenRouterNow) {
        test.skip(true, 'OpenRouter lane is unavailable in this build profile');
    }

    await expect(settingsDrawer).toBeVisible({ timeout: 5000 });
    const connectionTab = page.locator('[data-settings-tab="connection"]');
    await connectionTab.scrollIntoViewIfNeeded().catch(() => {});
    await connectionTab.click({ timeout: 8000, force: true }).catch(() => {});
    await page.waitForTimeout(150);
    await drawerScroll.evaluate((el) => {
        try {
            el.scrollTop = 0;
        } catch {
            /* ignore */
        }
    }).catch(() => {});
    await providerSelect.scrollIntoViewIfNeeded().catch(() => {});
    await page.waitForTimeout(100);
    // CI: select must be in view and actionable; default 30s is tight when the drawer body is scrolled.
    await providerSelect.selectOption('openrouter', { timeout: 60000 });
    await expect(providerSelect).toHaveValue('openrouter');
    // "Go Offline" sits below the fold — scroll after provider change re-renders.
    await drawerScroll.evaluate((el) => {
        try {
            el.scrollTop = el.scrollHeight;
        } catch {
            /* ignore */
        }
    }).catch(() => {});
    await page.waitForTimeout(150);
    // Prefer accessible name — survives DOM nesting / attribute quirks vs chained testids on CI.
    const killBtn = settingsDrawer.getByRole('button', { name: 'Go Offline' });
    await dismissBlockingOverlays({ budgetMs: 8000 }).catch(() => {});
    await killBtn.scrollIntoViewIfNeeded().catch(() => {});
    await expect(killBtn).toBeVisible({ timeout: 30000 });
    // Shares `disabled={busy}` with bridge actions — wait for DOM + enabled, not a blind sleep.
    await expect(killBtn).toBeEnabled({ timeout: 60000 });

    await killBtn.click({ timeout: 45000 });
    await expect(providerSelect).toHaveValue('ollama', { timeout: 60000 });
    await closeBtn.click({ timeout: 45000 }).catch(async () => {
        await closeBtn.click({ force: true, timeout: 15000 });
    });
    await expect(settingsDrawer).toBeHidden({ timeout: 20000 });
});

