async function collectShellBootstrapDiagnostics(page, rendererCrashed) {
    const url = await page.url().catch(() => '(url unknown)');
    let payload = '';
    try {
        payload = await page.evaluate(() => {
            const bar = document.querySelector('[data-testid="top-status-bar"]');
            const len = document.body && document.body.innerText ? document.body.innerText.length : 0;
            const excerpt = document.body && document.body.innerText
                ? String(document.body.innerText).slice(0, 900).replace(/\s+/g, ' ').trim()
                : '';
            return JSON.stringify({
                topStatusBarInDom: Boolean(bar),
                bodyTextLen: len,
                excerpt,
            });
        });
    } catch (e) {
        payload = JSON.stringify({ evaluateError: e && e.message ? e.message : String(e) });
    }
    return `shell bootstrap diagnostics: url=${url} rendererCrashed=${Boolean(rendererCrashed)} ${payload}`;
}

