async function settingsReadinessSnapshot(pg = page) {
    try {
        return await pg.evaluate(() => {
            const safe = (fn) => {
                try {
                    return fn();
                } catch (err) {
                    return { error: err && err.message ? err.message : String(err) };
                }
            };

            const visibleInfo = (el) =>
                safe(() => {
                    if (!el) return { exists: false, visible: false };

                    const rect = el.getBoundingClientRect();
                    const style = window.getComputedStyle(el);

                    return {
                        exists: true,
                        visible:
                            rect.width > 0 &&
                            rect.height > 0 &&
                            style.display !== 'none' &&
                            style.visibility !== 'hidden' &&
                            Number(style.opacity || '1') > 0,
                        rect: {
                            x: Math.round(rect.x),
                            y: Math.round(rect.y),
                            width: Math.round(rect.width),
                            height: Math.round(rect.height),
                        },
                        display: style.display,
                        visibility: style.visibility,
                        opacity: style.opacity,
                        pointerEvents: style.pointerEvents,
                        disabled: Boolean(el.disabled),
                        ariaHidden: el.getAttribute('aria-hidden'),
                        dataState: el.getAttribute('data-state'),
                        dataReady: el.getAttribute('data-ready'),
                        dataActive: el.getAttribute('data-active'),
                        text: (el.textContent || '').trim().slice(0, 300),
                    };
                });

            const q = (selector) =>
                safe(() => {
                    const nodes = Array.from(document.querySelectorAll(selector));
                    return {
                        selector,
                        count: nodes.length,
                        first: visibleInfo(nodes[0]),
                        visibleCount: nodes.filter((el) => Boolean(visibleInfo(el).visible)).length,
                    };
                });

            return {
                ok: true,
                url: location.href,
                readyState: document.readyState,
                viewport: {
                    width: window.innerWidth,
                    height: window.innerHeight,
                    scrollX: window.scrollX,
                    scrollY: window.scrollY,
                },
                root: q('#root'),
                drawer: q('[data-testid="settings-drawer"]'),
                drawerOpen: q('[data-testid="settings-drawer"][data-state="open"]'),
                connectionTab: q('[data-testid="settings-tab-connection"]'),
                activeConnectionTab: q('[data-testid="settings-tab-connection"][data-active="true"]'),
                connectionPanel: q('[data-testid="settings-panel-connection"]'),
                controls: q('[data-testid="settings-connection-controls"]'),
                provider: q('[data-testid="settings-provider-select"]'),
                kill: q('[data-testid="settings-offline-kill-btn"]'),
                close: q('[data-testid="settings-close-btn"]'),
                overlays: {
                    dialogs: q('[role="dialog"]'),
                    modals: q('[aria-modal="true"]'),
                    palette: q('[data-testid="command-palette"]'),
                },
                bodyText: safe(() => (document.body.innerText || '').slice(0, 1500)),
            };
        });
    } catch (err) {
        return {
            ok: false,
            outerError: err && err.message ? err.message : String(err),
        };
    }
}

/** On assertion failure, attach DOM truth without masking the original error. */
async function withReadinessDiagnostics(fn) {
    try {
        return await fn();
    } catch (err) {
        const snapshot = await settingsReadinessSnapshot();
        await test.info().attach('settings-readiness-snapshot.json', {
            body: JSON.stringify(snapshot, null, 2),
            contentType: 'application/json',
        });
        appendOfflineKillCiSummary(`- **readiness-failure** ${JSON.stringify(snapshot)}`);
        throw err;
    }
}

