async function offlineKillDomAfterProviderSnapshot() {
    try {
        return await page.evaluate(() => {
            const all = (selector) =>
                Array.from(document.querySelectorAll(selector)).map((el) => {
                    const rect = el.getBoundingClientRect();
                    const style = window.getComputedStyle(el);
                    return {
                        selector,
                        text: (el.textContent || '').trim().slice(0, 200),
                        display: style.display,
                        visibility: style.visibility,
                        opacity: style.opacity,
                        rect: {
                            x: Math.round(rect.x),
                            y: Math.round(rect.y),
                            width: Math.round(rect.width),
                            height: Math.round(rect.height),
                        },
                        dataState: el.getAttribute('data-state'),
                        dataActive: el.getAttribute('data-active'),
                        dataReady: el.getAttribute('data-ready'),
                    };
                });

            return {
                drawers: all('[data-testid="settings-drawer"]'),
                openDrawers: all('[data-testid="settings-drawer"][data-state="open"]'),
                panels: all('[data-testid="settings-panel-connection"]'),
