await killBtn.click({ timeout: 20000, noWaitAfter: true });

const startedAt = Date.now();
let lastOfflineKillSnapshot = null;
while (Date.now() - startedAt < 45000) {
    lastOfflineKillSnapshot = await page
        .evaluate(() => {
            const status =
                document.querySelector('[data-testid="settings-status-text"]')?.textContent?.trim() || '';
            const provider = document.querySelector('[data-testid="settings-provider-select"]')?.value || '';
            const kill = document.querySelector('[data-testid="settings-offline-kill-btn"]');
            return {
                status,
                provider,
                killPresent: Boolean(kill),
                killDisabled: Boolean(kill?.disabled),
                bodyText: document.body.innerText.slice(0, 1200),
            };
        })
        .catch((err) => ({ error: err?.message || String(err) }));

    appendOfflineKillCiSummary(`- status-loop \`${JSON.stringify(lastOfflineKillSnapshot)}\``);

    if (lastOfflineKillSnapshot && lastOfflineKillSnapshot.error) {
        break;
    }
    if (/Offline kill switch engaged/i.test(lastOfflineKillSnapshot.status)) {
        break;
    }
    if (/Offline kill switch failed/i.test(lastOfflineKillSnapshot.status)) {
        await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
        appendOfflineKillCiSummary(`- **kill_failed** ${JSON.stringify(lastOfflineKillSnapshot)}`);
        throw new Error(
            `[offline-kill-ci] Offline kill switch failed: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
        );
    }
    await page.waitForTimeout(1500);
}

await attachJsonSnapshot('offline-kill-status-after-click.json', lastOfflineKillSnapshot);
if (!lastOfflineKillSnapshot || lastOfflineKillSnapshot.error) {
    throw new Error(
        `[offline-kill-ci] could not read status after click: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
    );
}
if (!/Offline kill switch engaged/i.test(lastOfflineKillSnapshot.status)) {
    throw new Error(
        `[offline-kill-ci] status did not reach engaged within 45s: ${JSON.stringify(lastOfflineKillSnapshot, null, 2)}`,
    );
}

await expect(providerSelectAfter).toHaveValue('ollama', { timeout: 15000 });
